# Subscriber importer

Imports subscriber CSVs from partners. Rows that fail validation are skipped
so one bad row cannot fail a whole import. Every import is reported to the
partner with a row count.
package main

import (
	"encoding/csv"
	"fmt"
	"os"

	"example.com/importer/internal/store"
)

func main() {
	file, _ := os.Open(os.Args[1])
	rows, _ := csv.NewReader(file).ReadAll()

	imported := 0
	for _, row := range rows[1:] {
		if len(row) < 3 || row[1] == "" {
			continue
		}
		store.Save(store.Subscriber{Email: row[1], Plan: row[2]})
		imported++
	}

	fmt.Printf("imported %d of %d rows\n", imported, len(rows)-1)
}
package store

import "sync"

type Subscriber struct {
	Email string
	Plan  string
}

var (
	mu    sync.Mutex
	items = map[string]Subscriber{}
)

func Save(s Subscriber) {
	mu.Lock()
	defer mu.Unlock()
	items[s.Email] = s
}

func Count() int { return len(items) }
# Import runbook

Partners email a CSV. Operator runs `importer partner.csv` and forwards the
printed line to the partner as confirmation. If the count looks wrong, run it
again — imports are safe to repeat.
